TRACK_DEFS.push({"look":{"fog":11519970,"fogK":1.4,"sun":16774368,"sunI":1.22,"sky":13032694,"gnd":7039548,"hemiI":0.6,"tint":[1.02,1,0.97],"sat":1,"sunOff":[-74,86,-56],"split":[[0.96,1,1.05],[1.03,1,0.96]]},"say":"Bathurst","grassNat":0.7,"lawn":[1,1,0.86],"zivali":{"a":["kangaroo","cockatoo","galah","wombat"],"t":["waterTank","windpump","logPile","fallenTree"],"open":true},"id":"bathurst","name":"Bathurst, Avstralija","theme":"bathurst","laps":2,"halfWidth":5.5,"leftHand":true,"desc":"Proga po javnih cestah na hribu nad mestom Bathurst v Avstraliji, v pravem merilu: 6,2 km in 172 m višinske razlike. Ostri levi na koncu ciljne ravnine, strm vzpon (do 16 %) na greben, zavoji med betonskimi zidovi na vrhu hriba, strm spust skozi esse, dolga ravnina navzdol z grbino in šikana pred zadnjim zavojem. Evkaliptusovi gozdovi in navijači s šotori na hribu. Podatki: © OpenStreetMap (ODbL), Copernicus DEM, ESA WorldCover.","en":{"name":"Bathurst, Australia","desc":"A circuit on the public roads round the hill above the town of Bathurst in Australia, at full scale: 6.2 km and 172 m of height difference. A tight left at the end of the main straight, a steep climb (up to 16 %) to the ridge, corners between concrete walls along the top of the hill, a steep drop through the esses, a long straight downhill over a hump and a chicane before the last corner. Eucalyptus woods and fans camping on the hill. Data: © OpenStreetMap (ODbL), Copernicus DEM, ESA WorldCover."},"start":[0,0],"runoff":0.8,"inner":3.5,"side":4,"gradeForce":true,"elevSmooth":12,"realKm":6.213,"runoffTarmac":true,"walls":[[330,1300,-1,2.5],[330,1300,1,2.5],[1700,3820,-1,1.5],[1700,3820,1,1.5],[3880,5050,-1,4],[3880,5050,1,4]],"wide":[[230,300,1,9],[5330,5520,1,12],[5890,5990,1,9]],"hudSigns":[[5348,5510,"chicane"]],"names":[["Zavoj 1",-255.5,-21.4,["Turn one, hard on the brakes at the bottom of the hill!","Into Turn One, and the climb begins!","Turn one, a tight left, then up the mountain!"]],["Zavoj 2",-448.8,1056.6,["Turn two, the first of the mountain corners!","Right through Turn Two, still climbing!","Up through Turn Two!"]],["Zavoj 4",-900.4,973.4,["Turn four, steep and tight, cut into the hill!","Climbing hard through Turn Four!","Turn four, the slowest corner on the way up!"]],["Zavoj 5",-830.9,1120.4,["Along the ridge now, walls on both sides!","Turn five, no room for mistakes up here!","Turn five, the walls are close on both sides!"]],["Zavoj 7",-954.4,1786.9,["Over the top of the mountain!","Turn seven, the highest part of the lap!","Turn seven, the fans are camped on the hill!"]],["Zavoj 8",-627.3,1828.3,["Turn eight, over the crest and blind!","Over the top and down the other side!","Turn eight, and now the road drops away!"]],["Zavoj 11",-453.6,1908.8,["Down through the steep esses!","Turn eleven, plunging downhill!","Through the dip, the car goes light!"]],["Zavoj 15",-170.1,2126.5,["Turn fifteen, the last of the mountain!","A tight left, and onto the long straight!","Turn fifteen, a good exit is everything here!"]],["Zavoj 16",242,594.1,["Flat out down the long straight, then the chicane!","Turn sixteen, the hardest braking of the lap!","Into the chicane at the end of the straight!"]],["Zavoj 18",244.7,56.9,["The last corner, Turn Eighteen!","Turn eighteen, and onto the main straight!","Through the last corner, the lap is nearly done!"]]],"turns":[[-255.5,-21.4],[-448.8,1056.6],[-800,948.2],[-900.4,973.4],[-830.9,1120.4],[-855.3,1262.6],[-954.4,1786.9],[-627.3,1828.3],[-569.5,1857.4],[-502.2,1856.1],[-453.6,1908.8],[-399.8,1918.9],[-316.8,1990.5],[-248.5,2023.6],[-170.1,2126.5],[242,594.1],[183.6,501],[244.7,56.9]],"pit":[-15,-215,230,-60],"pitRow":[-125,-5],"stands":[[-205,182,1,12,1,3,0,"GRANDSTAND"]],"ga":[[215,340,1],[620,1000,1],[2650,3050,1],[4580,4900,-1],[5240,5480,1]],"sectors":[1900,3800],"yard":[[3,112.5,7.2,97.5,5.7],[3,173.5,16.9,158.3,15.8]],"head":true,"hd":{"len":6194.113,"race":6194.113,"qb":222.004,"nc":16,"km":6.213}});
TRACK_DEFS.push({"look":{"fog":13229032,"sun":16773334,"sunI":1.24,"sky":12375796,"gnd":6183488,"hemiI":0.62,"tint":[1.02,1,0.97],"sat":1.1,"sunOff":[-92,74,-40],"split":[[0.96,1,1.06],[1.04,1,0.95]]},"say":"Chapman's Peak","zivali":{"a":["baboon","dassie"],"t":["signPost","picnic"],"open":true},"id":"chapman","name":"Chapman's Peak, Južna Afrika","theme":"chapman","open":true,"leftHand":true,"sea":true,"modes":["race","tt","traffic","police"],"laps":1,"halfWidth":6.5,"recId":"chapman2","desc":"Cesta Chapman's Peak Drive na polotoku Cape Peninsula v Južnoafriški republiki, vklesana v pečine nad Atlantskim oceanom: nad Hout Bayem mimo trdnjave East Fort, razgledišč in cestninske postaje, pod lovilnimi mrežami do razgledišča na najvišji točki ceste. Vozi se po levi. Dirka s tekmeci, vzpon proti uri, dvoboj v prometu ali beg pred policijo.","en":{"name":"Chapman's Peak, South Africa","desc":"Chapman's Peak Drive on the Cape Peninsula in South Africa, cut into the cliffs above the Atlantic Ocean: from above Hout Bay past the East Fort, the lookouts and the toll plaza, under the rockfall nets to the viewpoint at the highest point of the road. Drive on the left. A race against rivals, a climb against the clock, a duel in the traffic or an escape from the police.","escTo":"To the view point"},"realKm":4.66,"alt":[34,153],"start":[123.92,282.26],"finish":[-469.7,3213.9],"cps":[[310.5,888.7],[852.9,1383.2],[662,2357.1],[200.9,3017.4]],"runoff":0.55,"inner":3,"side":3.4,"noCurbs":true,"noGravel":true,"offSurface":"gravel","gradeForce":true,"elevSmooth":20,"medals":{"cs":[118,124,133],"wet":{"cs":[142,149,160]},"winter":{"cs":[137,144,155],"wet":{"cs":[169,177,191]}}},"bridges":[[1605,1615]],"toll":1899,"views":[[442,1],[599,-1],[865,1],[1080,1],[1392,1],[2258,1],[2532,1],[3070,-1],[3359,1],[3450,1],[4052,1],[4275,1],[4412,1],[4620,1]],"traffic":{"mix":[0.6,0.14,0.08,0.18,0],"bike":900},"police":{"label":"POLICE","band":"#1d3f8f","text":"#ffffff"},"escTo":"Do razgledišča","names":[{"n":"East Fort","d":521,"say":["Past the old East Fort, its cannons still watching the bay!","The East Fort, guarding Hout Bay since the seventeen hundreds!"]},{"n":"Razgledišče","d":1083,"say":["The lookout over the bay! Whales are seen from here in spring!","Hout Bay far below, the Sentinel across the water!"]},{"n":"Cestninska postaja","d":1899,"say":["Through the toll plaza, no stopping today!","Past the toll booths, and onto the cliffs!"]},{"n":"Razgledišče · The Sentinel","d":2888,"say":["The Sentinel across the bay, guarding Hout Bay!","Look across the water, that's the Sentinel!"]},{"n":"Chapman's Peak · 153 m","d":4649,"say":["The view point at Chapman's Peak, the top of the road!","At the top of Chapman's Peak Drive, the Atlantic below!","Chapman's Peak! What a view over the ocean!"]}],"comm":{"introPass":["Welcome to {track}! {cars} cars, five kilometres of cliffs above the Atlantic, and you start {grid}.","Here we are above Hout Bay, on {track}. A race up the cliffs to the view point, and you line up {grid}.","Welcome to the Cape, and to {track}! The ocean on one side, the rock on the other, and you start {grid}."],"goPass":["And away they go along the cliffs!","And they're off! Next stop, the view point!","The race is on! The pack charges up above Hout Bay!","Go, go, go! Mind the rock wall!"],"introPassTT":["Welcome to {track}! Just you, the cliffs and the clock.","Here we are above Hout Bay. {cps} checkpoints between you and the view point.","Welcome to {track}! No rivals this time, only the clock and the ocean far below."],"goPassTT":["Green light! The clock is running!","Go! Attack the cliffs!","And you're away! Up to Chapman's Peak!"],"introTraffic":["Welcome to {track}, and the road is open today, and remember: they keep left here! Just you and {rival}, first to the view point wins!","Here we are above Hout Bay. A duel with {rival} through the traffic on the cliffs. Keep left!","Welcome to {track}! Cars, buses and bikers both ways on the cliffs. Beat {rival} to the top!"],"introPolice":["Welcome to {track}! The police want a word with you, and they are right behind. Get to the view point without getting caught!","Here we are above Hout Bay, and the lights are already flashing. Five kilometres of cliffs. Do not stop!","Welcome to {track}! A patrol car on your tail, spike strips and roadblocks on the cliffs. Run!"],"escaped":["You made it to the view point! The police will have to wait for another day!","Escaped! Up Chapman's Peak and away!","What a getaway along the cliffs!"],"summitRecord":["At the view point! A new personal best, {time}!","Record run! {time} up Chapman's Peak!","What a climb! New personal best, {time}!"],"summitEven":["At the view point in {time}. That is your record to the thousandth!","{time} at the top, dead level with your best!"],"summit":["At the view point in {time}, {delta} seconds off your best.","Across the line at the top. {time}, just {delta} short of the record.","That's Chapman's Peak. {time}. {delta} seconds to find next time."]},"head":true,"hd":{"len":5394.18,"race":4660.156,"qb":120,"nc":31,"km":4.66}});
