TRACK_DEFS.push({"look":{"fog":13226452,"sun":16773340,"sunI":1.18,"sky":9286614,"gnd":6122308,"hemiI":0.64,"tint":[1,1.01,0.99],"sat":1.04,"sunOff":[70,92,-48],"split":[[0.97,1,1.05],[1.04,1,0.94]]},"say":"the Mã Pí Lèng pass","rainP":0.3,"zivali":{"a":["cowB","horse","goatW","pig"],"t":[],"open":true},"id":"mapileng","name":"Mã Pí Lèng, Vietnam","theme":"mapileng","open":true,"modes":["race","tt","traffic","police"],"laps":1,"halfWidth":4.5,"maxRivals":95,"desc":"Cesta QL4C na kraški planoti Đồng Văn na skrajnem severu Vietnama: najbolj zavit kilometer ceste iz Đồng Văna proti prelazu Mã Pí Lèng, pet ovinkov in tri serpentine v strmem pobočju sivega apnenca, od 1184 m do 1256 m. Spomenik graditeljem ceste z majhno kapelico, muzej in kavarna ob cesti, steza ob steni in razgledišče tik za ciljem, kraški vrhovi naokrog in koruza med skalami. Dirka, vožnja na čas, dvoboj v prometu in beg pred policijo.","en":{"name":"Mã Pí Lèng, Vietnam","desc":"The road QL4C on the karst plateau of Đồng Văn in the far north of Vietnam: the twistiest kilometre of the road from Đồng Văn towards the Mã Pí Lèng pass, five corners and three hairpins up a steep slope of grey limestone, from 1184 m to 1256 m. A memorial to the road's builders with a small shrine, a museum and a café by the road, a cliff path and a viewpoint just past the finish, karst peaks all round and maize between the rocks. A race, a time trial, a duel in the traffic and a run from the police.","escTo":"To the Mã Pí Lèng pass"},"runoff":0.5,"inner":2.6,"side":3,"noCurbs":true,"noGravel":true,"offSurface":"gravel","gradeForce":true,"elevSmooth":6,"medals":{"cs":[37,38,41],"wet":{"cs":[40,42,45]}},"traffic":{"mix":[0.26,0.16,0.08,0.44,0.06],"bike":5000},"police":{"label":"CẢNH SÁT","band":"#1c3f8c","text":"#f6f2e4"},"escTo":"Do prelaza Mã Pí Lèng","names":[{"n":"Serpentina 1 · 1.210 m","d":357,"say":["Hairpin one, and the climb bites!","Into the first hairpin, the limestone right beside you!"]},{"n":"Serpentina 2 · 1.216 m","d":438,"say":["Hairpin two, straight after the first one!","Hairpin two! Right back the other way!"]},{"n":"Serpentina 3 · 1.243 m","d":716,"say":["Hairpin three, the last of them!","The third hairpin, and the top of the climb is close!"]},{"n":"Spomenik","d":855,"say":["Past the memorial to the road's builders, the top of the climb!","The memorial on the right, and the finish just over the crest!"]}],"comm":{"introPass":["Welcome to {track}! {cars} cars, one kilometre of the twistiest road on the karst plateau, three hairpins up the limestone, and you start {grid}.","Here we are below the Mã Pí Lèng pass, on the road up from Đồng Văn. One short climb, three hairpins, and you line up {grid}.","Welcome to the far north of Vietnam! {cars} cars on a kilometre of hairpins, and you start {grid}."],"goPass":["And away they go, up towards the pass!","And they're off! Three hairpins to the top!","The race is on! Up the limestone they go!"],"introPassTT":["Welcome to {track}! Three hairpins and the karst all round, just you and the clock.","Here we are on the road up from Đồng Văn. {cps} checkpoints between you and the finish over the crest.","Welcome to {track}! No rivals this time, only the clock and the hairpins."],"goPassTT":["Green light! The clock is running!","Go! Attack the hairpins!","And you're away! Up towards the pass!"],"introTraffic":["Welcome to {track}, and the road is open today: motorbikes, cars and the minibuses both ways on a narrow mountain road. Just you and {rival}, first to the finish wins!","Here we are below the Mã Pí Lèng pass. A duel with {rival} through the traffic. Mind the motorbikes in the hairpins!"],"introPolice":["Welcome to {track}! The police want a word with you, and they are right behind. Up the hairpins and over the crest without getting caught!","Here we are on the road up from Đồng Văn, and the lights are already flashing. One kilometre to the crest. Do not stop!"],"escaped":["You made it over the crest! The police will have to wait for another day!","Escaped! Up the hairpins and away towards the pass!"],"summitRecord":["At the finish! A new personal best, {time}!","Record run! {time} up the three hairpins!","What a drive! New personal best, {time}!"],"summitEven":["At the finish in {time}. That is your record to the thousandth!","{time} at the finish, dead level with your best!"],"summit":["At the finish in {time}, {delta} seconds off your best.","Across the line over the crest. {time}, just {delta} short of the record.","That's the road to the Mã Pí Lèng pass. {time}. {delta} seconds to find next time."]},"alt":[1184,1245],"realKm":0.99,"finish":[542.6,160.5],"cps":[[283,38.3],[430.9,-31.2]],"curves":[[357,1210,1],[438,1216,-1],[716,1243,1]],"lc":{"x0":-544,"z0":-688,"nx":102,"nz":98,"cell":16,"rle":"HWLH_cLH_bLH_LKHEMFLH-_YOH_JKBKFNH_LPAFNH_IPCH_UPCH_VOH_XMH_aKHa"},"views":[[605.1,356.9]],"boards":[[429.8,73.8]],"marks":[[435.2,83.8,"monument"],[475.9,83.2,"museum"],[421,70.1,"shrine"],[409.7,74.7,"cafe"]],"paths":[[-20.6,-53.7,22.4,-190.6,-10,-205.9],[503.3,84.1,533.7,77.4,555.9,69.4,576.1,69.4,586.9,65],[469.9,66.4,472.6,63.7]],"bld":[],"rocks":[],"cliffs":[],"trees":[],"stops":[],"start":[0,0],"head":true,"hd":{"len":1457.762,"race":989.838,"qb":400,"nc":10,"km":0.99}});
